package com.example.recyclerviewdemostracion

import android.os.Bundle
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView

class MainActivity : AppCompatActivity() {

    private lateinit var recyclerView: RecyclerView
    private lateinit var adapter: personajeAdapter

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        recyclerView = findViewById(R.id.recyclerView)
        recyclerView.layoutManager = LinearLayoutManager(this)

        val listaPersonajes = listOf(
            Personaje("Goku", "Dragon Ball", "data:image/jpeg;base64,"),
            Personaje("John Nolan", "The Rookie", "data:image/jpeg;base64,"),
            Personaje("Monkey D. Luffy", "One Piece", "data:image/jpeg;base64,"),
            Personaje("Walter White", "Breaking bad", "data:image/jpeg;base64,"),
            Personaje("Dexter Morgan", "Dexter", "data:image/jpeg;base64,"),
            Personaje("Geralt of Rivia", "The Witcher", "data:image/jpeg;base64,"),
            Personaje("Joe Goldberg", "You", "data:image/jpeg;base64,")
        )

        adapter = personajeAdapter(listaPersonajes)

        recyclerView.adapter = adapter

    }
}